custom_css:
/* 《情歌》@夜行性鲨鱼
禁商用禁二传禁二改（也给我吃一口的话可以二改₍ᐢ.ˬ.ᐢ₎
带符号♥的地方是自定义文字区域 */
/* ------------------------------------------------------------
   1. 全局UI与扁平化基础
   ------------------------------------------------------------ */
* { border-radius: 0 !important; }
::-webkit-scrollbar { display: none; }
#top-bar { margin: 0 auto; left: 0; right: 0; display: inline-block; height: 24px; position: absolute; box-shadow: none; opacity: 0; z-index: 3005; }
.drawer-icon { transform: scale(0.55); color: #000; }

/* 面板与控件扁平化 */
.drawer-content .range-block, .inline-drawer-header h4, .standoutHeader, h4, h4[data-i18n] {
    border: none !important; background: transparent !important; box-shadow: none !important; color: #555 !important; text-shadow: none !important; margin-bottom: 5px !important; border-bottom: 1px dashed #E0E0E0 !important; padding-bottom: 5px !important;
}
.text_pole, textarea, select, .menu_button, .character_select, .group_select, input[type="text"], input[type="number"] {
    background-color: #fff !important; border: 1px solid #E0E0E0 !important; color: #444 !important; box-shadow: none !important; transition: all 0.2s ease;
}
.menu_button { background-color: #FAFAFA !important; }
.text_pole:focus, textarea:focus, select:focus { border-color: #AAA !important; background-color: #fff !important; outline: none !important; }
.menu_button:hover { background-color: #F0F0F0 !important; color: #000 !important; }
#completion_prompt_manager_list { background-color: transparent !important; border: none !important; }
#completion_prompt_manager_list .completion_prompt_manager_prompt_name.text_muted, #completion_prompt_manager_list .text_muted, .completion_prompt_manager_prompt_name {
    color: #555 !important; opacity: 1 !important; -webkit-text-fill-color: #555 !important; text-shadow: none !important;
}

/* ------------------------------------------------------------
   2. 核心修复：气泡容器与右侧空隙填补 (统一所有楼层)
   ------------------------------------------------------------ */
body.bubblechat .mes, body.bubblechat .mes[is_user="true"], .mes {
    padding: 360px 12px 35px 12px !important;/* 顺序是：上 右 下 左 */
    max-width: 360px !important; /* 锁定宽度，杜绝变形 */
    margin: 30px auto 15px auto !important;
    background-color: #FFFEFB !important; 
    background-image: none !important;
    border: 0.5px solid #D0D0D0 !important;
    box-shadow: 4px 4px 15px rgba(0,0,0,0.05) !important;
    position: relative !important;
    overflow: visible !important;
    box-sizing: border-box !important;
}

/* 修复正文右侧大片空档：强行铺满宽度，去除酒馆原生预留边距 */
.mes_block {
    width: 100% !important; max-width: 100% !important; padding: 0 !important; margin: 0 !important; display: block !important;
}
.mes_text {
    width: 100% !important; max-width: 100% !important; 
    padding: 0 !important; margin: 0 !important; 
    text-align: justify !important; text-justify: inter-ideograph !important; 
    box-sizing: border-box !important;
}

/* ------------------------------------------------------------
   3. 杂志封面设计 (满铺无渐隐) 
   ------------------------------------------------------------ */
.mesAvatarWrapper {
    width: calc(100% - 24px) !important;
    height: 330px !important;
    position: absolute !important;
    top: 12px !important; left: 12px !important;
    z-index: 2 !important;
    background: #F2F2F2 !important;
    overflow: hidden !important;
    border: none !important;
    padding: 0 !important; margin: 0 !important;
}

.mesAvatarWrapper .avatar, .mesAvatarWrapper .avatar img {
    width: 100% !important; height: 100% !important; object-fit: cover !important;
    filter: contrast(1.02) !important;
    -webkit-mask-image: none !important; mask-image: none !important; /* 彻底去除渐隐 */
    border: none !important; box-shadow: none !important;
}

/* 纵向大标题与水印装饰 */
.mes .name_text {
    position: absolute !important;
    writing-mode: vertical-rl !important;
    top: 25px !important; right: 25px !important;
    font-weight: 900 !important; font-size: 2em !important;
    color: #1a1a1a !important; letter-spacing: 0.2em !important;
    z-index: 10 !important; line-height: 1 !important;
    text-shadow: 2px 2px 0px #fff, -1px -1px 0px #fff, 1px -1px 0px #fff, -1px 1px 0px #fff !important;
}
/* ♥自定义-红色小标 */
.mesAvatarWrapper::after {
    content: "♪情歌" !important;
    position: absolute !important; top: 0; left: 0;
    background: #A62424 !important; color: #fff !important;
    font-size: 8px !important; padding: 3px 10px !important;
    letter-spacing: 1px !important; z-index: 11 !important;
}
.mes .timestamp {
    position: absolute !important; writing-mode: vertical-rl !important;
    top: 25px !important; right: 8px !important;
    font-size: 8.5px !important; color: #888 !important; z-index: 10 !important;
}
/* ♥自定义-头像底部 */
.mes::after {
    content: "“Un univers entier pour un haricot rouge.”" !important;
    position: absolute !important; top: 345px !important; left: 50% !important; transform: translateX(-50%) !important;
    font-size: 7px !important; color: #CCC !important; letter-spacing: 2px !important; white-space: nowrap !important;
}

/* 修复数据标签白块问题：去背景，加文字描边，绝对贴底对齐 */
.mes .mes_timer, .mes .mesIDDisplay, .mes .tokenCounterDisplay {
    background: transparent !important; /* 去除难看的白底 */
    color: #444 !important;
    font-size: 9px !important;
    padding: 0 0 0 6px !important;
    position: absolute !important;
    z-index: 12 !important;
    border-left: 2px solid #A62424 !important;
    white-space: nowrap !important;
    text-shadow: 1px 1px 0px #fff, -1px -1px 0px #fff, 1px -1px 0px #fff, -1px 1px 0px #fff !important; /* 白边确保能在任何图上读清 */
}
.mes .mesIDDisplay { left: 15px !important; bottom: 45px !important; top: auto !important; right: auto !important; }
.mes .mesIDDisplay::before { content: "UID. " !important; }
.mes .tokenCounterDisplay { left: 15px !important; bottom: 30px !important; top: auto !important; right: auto !important; transform: none !important; }
.mes .tokenCounterDisplay::after { content: " WORDS" !important; }
.mes .mes_timer { left: 15px !important; bottom: 15px !important; top: auto !important; right: auto !important; }
.mes .mes_timer::before { content: "DUR. " !important; }

/* ------------------------------------------------------------
   4. 思维链美化 (极简杂志分割线风格 - 拒绝套娃)
   ------------------------------------------------------------ */

/* 1. 彻底抹除所有外层容器的背景和边框 */
.mes_reasoning_details, 
.mes_reasoning_header {
    margin: 25px auto !important;
    padding: 0 !important;
    background: transparent !important;
    border: none !important;
    width: 100% !important;
    box-sizing: border-box !important;
}

/* 2. 重塑标题栏：取消方框，改为极简的上下分割线 */
.mes_reasoning_summary {
    background: transparent !important; /* 彻底透明 */
    border-top: 1px solid #A62424 !important; /* 只有顶部一条红线 */
    border-bottom: 1px solid #A62424 !important; /* 只有底部一条红线 */
    padding: 10px 0 !important;
    border-radius: 0 !important;
    color: #A62424 !important;
    display: flex !important;
    justify-content: center !important; /* 文字严格居中 */
    align-items: center !important;
    cursor: pointer;
    transition: all 0.3s ease;
    width: 90% !important; /* 宽度略微往里收一点，更有设计感 */
    margin: 0 auto !important;
    box-shadow: none !important;
}

/* 悬停效果：线条稍微加粗 */
.mes_reasoning_summary:hover {
    letter-spacing: 2px;
}

/* 3. 隐藏原本的标题文字 */
.mes_reasoning_header_title { display: none !important; }
/* 4. 自定义文字样式：加上音乐符号和间距 */
.mes_reasoning_header::before {
    content: "你和我 十指紧扣 默写前奏" !important;/* ♥自定义-思维链 */
    font-size: 11px !important;
    letter-spacing: 3px !important;
    color: #A62424 !important;
    font-weight: 400 !important;
    text-transform: uppercase;
}

/* 5. 隐藏右侧那些乱七八糟的图标（复制、编辑、折叠箭头等） */
/* 只保留一个淡淡的符号，甚至可以全关掉，让视觉更干净 */
.mes_reasoning_summary_icon, 
.mes_reasoning_summary_btns {
    display: none !important; 
}

/* 6. 思维链展开后的内容区：不加外框，只靠左侧一条红线标注 */
.mes_reasoning {
    background: #FFF !important;
    color: #888 !important;
    font-size: 0.9em !important;
    font-style: italic !important;
    line-height: 1.8 !important;
    padding: 20px 5% !important; /* 左右留白，与分割线对齐 */
    border: none !important; /* 去掉所有框 */
    border-left: 2px solid #A62424 !important; /* 仅左侧红线提示 */
    width: 80% !important; /* 内容稍微缩进，显得精致 */
    margin: 10px auto !important;
    text-align: justify !important;
    box-sizing: border-box !important;
}

/* ------------------------------------------------------------
   5. 正文文字样式美化 (拒绝残留色块)
   ------------------------------------------------------------ */

/* 1. 粗体：纯正红文字 */
.mes_text strong {
    background: transparent !important;
    color: #A62424 !important;
    font-weight: 800 !important;
}

/* 2. 斜体：正红心形 */
.mes_text em {
    position: relative !important; 
    padding-left: 18px !important; 
    color: #555 !important; 
    font-style: italic !important;
}
.mes_text em::before {
    content: '♥︎' !important;
    position: absolute !important; left: 0 !important; 
    color: #A62424 !important; top: 0 !important;
}

/* 3. 彻底清除行内/块状代码的黑色 (解决你图中的黑条问题) */
.mes_text code, 
.mes_text pre, 
.mes_reasoning code, 
.mes_reasoning pre {
    background: #FFF !important;
    color: #A62424 !important; /* 行内代码统一改红字，更和谐 */
    border: 1px solid #A62424 !important;
    border-radius: 0 !important;
    text-shadow: none !important;
}

/* 4. 代码块/引用块：正红白底布局 */
.mes_text pre, .mes_reasoning pre {
    padding: 35px 15px 15px 15px !important; 
    margin: 20px 0 !important;
    position: relative !important; 
    width: 100% !important;
    box-sizing: border-box !important;
    overflow-x: auto !important;
}

/* 5. 消除代码块内部嵌套标签产生的多余黑色 */
.mes_text pre > code {
    border: none !important;
    padding: 0 !important;
    color: #444 !important; /* 大段代码文字用深灰，保护眼睛 */
    display: block !important;
}

/* 6. NOTE 标签：正红底白字 */
.mes_text pre::before, .mes_reasoning pre::before {
    content: 'NOTE' !important; /* ♥自定义 */
    position: absolute !important; 
    top: 0 !important; left: 0 !important;
    background: #A62424 !important; 
    padding: 3px 15px !important; 
    font-size: 11px !important; 
    color: #FFF !important; 
    font-weight: bold !important;
    letter-spacing: 2px !important;
    z-index: 5;
}

/* ------------------------------------------------------------
   6. 控件美化 (滑块独立隔离、复选框、输入栏)
   ------------------------------------------------------------ */
/* 滑块完全独立隔离 */
input[type="range"] {
    -webkit-appearance: none !important; appearance: none !important;
    background: #000000 !important; height: 4px !important;
    border: none !important; box-shadow: none !important; outline: none !important;
    filter: none !important; mix-blend-mode: normal !important; opacity: 1 !important;
}
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none !important; appearance: none !important;
    width: 30px !important; height: 30px !important;
    background: url('https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAERfYZpqwtmOoaTB8Qji_pF2baEkGQAAa4AAg8nAAIZNFlVL5uxQ2TIkbE6BA.png') center/contain no-repeat !important; background-color: transparent !important; 
    cursor: pointer !important; border: none !important; box-shadow: none !important;
    filter: none !important; opacity: 1 !important; mix-blend-mode: normal !important; image-rendering: -webkit-optimize-contrast !important;
}
input[type="range"]::-moz-range-thumb {
    width: 30px !important; height: 30px !important;
    background: url('https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAERfYZpqwtmOoaTB8Qji_pF2baEkGQAAa4AAg8nAAIZNFlVL5uxQ2TIkbE6BA.png') center/contain no-repeat !important; background-color: transparent !important;
    border: none !important; filter: none !important; opacity: 1 !important; mix-blend-mode: normal !important;
}

/* ------------------------------------------------------------
   6. 控件美化 (复选框重设计 - 适配红豆/杂志风格)
   ------------------------------------------------------------ */

/* 复选框基础方框 */
input[type="checkbox"] {
    -webkit-appearance: none; 
    appearance: none;
    width: 15px !important; 
    height: 15px !important; 
    background-color: #FFF !important; 
    border: 1px solid #D0D0D0 !important; /* 浅色边框，不突兀 */
    position: relative;
    display: inline-block;
    vertical-align: middle;
    cursor: pointer;
    transition: all 0.2s ease;
    margin-right: 8px !important;
}

/* 鼠标悬停时边框变色 */
input[type="checkbox"]:hover {
    border-color: #A62424 !important; /* 悬停变为主题红 */
}

/* 选中状态：背景变红 */
input[type="checkbox"]:checked {
    background-color: #A62424 !important; /* 使用主题里的红豆色 */
    border-color: #A62424 !important;
}

/* 选中后的对勾：改用更细、更精致的比例 */
input[type="checkbox"]:checked::after {
    content: '';
    position: absolute;
    left: 4px; 
    top: 1px; 
    width: 4px; 
    height: 8px;
    border: solid white;
    border-width: 0 1.5px 1.5px 0; /* 减小线条粗细 */
    transform: rotate(45deg);
    transition: all 0.2s ease;
}

/* 底部输入栏 */
#send_form { display: flex; flex-wrap: wrap; align-items: center; width: 94% !important; max-width: 800px; margin: 10px auto !important; background: #fff !important; border: 1px solid #DDD !important; box-shadow: 4px 4px 0 rgba(0,0,0,0.05) !important; }
#nonQRFormItems { padding: 4px 12px !important; position: relative; display: flex; flex-direction: row; column-gap: 5px; order: 25; width: 100%; min-height: 40px !important; align-items: center; background-color: #fff !important; border: none !important; box-shadow: none !important; z-index: 50; }
.qr--buttons { opacity: 0; visibility: hidden; max-height: 0; margin: 0 !important; padding: 0 !important; transform: translateY(15px); transition: all 0.3s cubic-bezier(0.2, 1, 0.3, 1); overflow: hidden; }
#send_form:focus-within .qr--buttons { opacity: 1; visibility: visible; max-height: 300px; margin-bottom: 8px !important; transform: translateY(0); pointer-events: auto; }
#rightSendForm > div:not(.mes_stop), #leftSendForm > div { transform: scale(0.6) !important; color: #000; }
#send_textarea::placeholder { color: transparent !important; }
#send_textarea { background-color: transparent !important; border: none !important; box-shadow: none !important; color: #333 !important; }
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { content: "一整个宇宙 换一颗红豆。"; position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); font-style: oblique; font-size: 0.5em; pointer-events: none; z-index: 10; white-space: nowrap; color: #999; }/* ♥自定义-输入框 */
#chat { -webkit-mask-image: linear-gradient(to bottom, transparent 0, black 15px, black calc(100% - 25px), transparent 100%); mask-image: linear-gradient(to bottom, transparent 0, black 15px, black calc(100% - 25px), transparent 100%); }
/* ------------------------------------------------------------
   7. 扩展面板与折叠栏修复 (去除脏灰色渐变)
   ------------------------------------------------------------ */

/* 彻底移除折叠栏标题的背景颜色、渐变和阴影 */
.inline-drawer-header, 
.collapsible-header, 
.extension-header {
    background-color: #FFF !important; /* 改为纯白 */
    background-image: none !important; /* 删掉那个难看的灰色渐变 */
    border: none !important;
    border-bottom: 1px dashed #E0E0E0 !important; /* 改为和你其它标题一样的虚线 */
    box-shadow: none !important;
    text-shadow: none !important;
    color: #444 !important; /* 文字改为深灰 */
    padding: 10px 5px !important;
    transition: all 0.2s ease;
}

/* 鼠标悬停时的效果：稍微变红或变灰 */
.inline-drawer-header:hover, 
.collapsible-header:hover {
    background-color: #FAFAFA !important;
    color: #A62424 !important; /* 悬停时文字变红 */
}

/* 修复右侧那个向下的小箭头 (V) */
.inline-drawer-icon, 
.fa-chevron-down, 
.fa-chevron-up {
    color: #A62424 !important; /* 箭头改用主题红 */
    opacity: 0.8;
    transform: scale(0.8); /* 稍微缩小一点，显得精致 */
}

/* 彻底清除那些包裹块的深黑色边框 */
.inline-drawer, 
.setup-item, 
.extension-settings {
    border: none !important;
    background: transparent !important;
    margin-bottom: 5px !important;
}
